export const HISTORY_EDITORIAL = {
  heading: "सम्पादकीय",
  body: "उपलब्ध रिकॉर्ड के अनुसार कानूनगो परिवार की उत्पत्ति ग्राम-नान अमरसर से हुई प्रतीत होती है। परिवार के सन 1558 (सम्वत 1615) में मुखिया श्री सेडमल जी दुसाद थे, जिन्हें जयपुर रियासत के महाराजा सवाई मानसिंह जी ने मुग़ल कालीन बादशाह सम्राट अकबर के आदेशानुसार कानूनगो की उपाधि प्रदान की। उन्हीं के वंशज श्री चोथमल जी तदुपरान्त ग्राम खेजरोली में सन 1643 में स्थानान्तरित हो गये। श्री चोथमल जी के छोटे सुपुत्र श्री रामचन्द्र जी ग्राम गोविन्दगढ़ में बस गये। ग्राम गोविन्दगढ़ में मौजूदा हवेली का निर्माण करीब 200 वर्ष पूर्व श्री महादेव जी एवं श्री गणेश नारायण जी कानूनगो द्वारा कराया गया था।\n\nसन 1930 के बाद परिवार के लोग रोज़गार के नये अवसरों के लिये देश के विभिन्न भागों में रहने लगे तथा परिवार के लोगों का आपसी संपर्क कम होने लगा; यहाँ तक कि जयपुर में रहने वाले परिवार के सदस्य भी आपस में दूरी महसूस करने लगे। इन हालात में परिवार के बुज़ुर्गों, विशेषतया श्री राम गोपाल जी कानूनगो के मार्गदर्शन में कानूनगो युवा समिति का गठन सन 1988 में किया गया। युवा समिति के तत्वावधान में नियमित बैठकें होती रहीं, आपसी मेल-जोल व भाईचारा बढ़ने लगा। इससे उत्साहित होकर मुम्बई में भी इसी के अनुरूप गतिविधियाँ होने लगीं।\n\nसन 1989 में युवा समिति जयपुर ने दीपावली के शुभ अवसर पर पारिवारिक स्नेह मिलन समारोह एवं अन्नकूट की प्रसादी का आयोजन प्रारम्भ किया, जो बदस्तूर जयपुर एवं मुम्बई में जारी है। ऐसे ही एक आयोजन में जयपुर में आपसी विचार-विमर्श के दौरान यह महसूस किया गया कि परिवार के सदस्य हिन्दुस्तान में अलग-अलग बस गये हैं; सभी पारिवारिक स्थितियों से आपस में अवगत रहें, इस उद्देश्य से परिवार की एक डायरेक्टरी बनाने का समिति द्वारा निर्णय लिया गया। इस कार्य का संयोजक श्री रमाकान्त कानूनगो को नियुक्त किया गया, जिनके अथक प्रयासों का प्रतिफल इस डायरेक्टरी के रूप में आपके सामने है।",
  signature: "राम रतन कानूनगो\nअध्यक्ष",
};

